formulas.rawText:
{
  "originalFormula": "p_h(0) = p_{0} \exp\\left(\\frac{eV_a}{kT}\\right)",
  "genericFormula": "p_h(0) = p_{0} \\exp\\left(\\frac{eV_a}{kT}\\right)",
  "description": "Esta fórmula representa a densidade de portadores de carga positiva (buracos) em um semicondutor em equilíbrio térmico, em função da densidade inicial de buracos, da energia de ativação e da temperatura. Ela mostra como a densidade de buracos varia com a aplicação de uma tensão e a temperatura do sistema.",
  "concepts": [
    "Densidade de portadores de carga",
    "Semicondutores",
    "Equilíbrio térmico",
    "Energia de ativação",
    "Efeito da temperatura"
  ],
  "symbols": [
    {
      "symbol": "p_h(0)",
      "description": "Representa a densidade de buracos no semicondutor em condições de equilíbrio térmico."
    },
    {
      "symbol": "p_{0}",
      "description": "Representa a densidade inicial de buracos antes da aplicação de qualquer tensão."
    },
    {
      "symbol": "e",
      "description": "Representa a base do logaritmo natural, uma constante matemática que é aproximadamente igual a 2.71828."
    },
    {
      "symbol": "V_a",
      "description": "Representa a energia de ativação, que é a quantidade de energia necessária para criar um buraco no semicondutor."
    },
    {
      "symbol": "k",
      "description": "Representa a constante de Boltzmann, que relaciona a temperatura com a energia em sistemas físicos."
    },
    {
      "symbol": "T",
      "description": "Representa a temperatura do sistema em Kelvin, uma medida da energia térmica média das partículas."
    }
  ]
}
